"use client";

/* eslint-disable react-hooks/set-state-in-effect */

import { useCallback, useEffect, useMemo, useState, type FormEvent } from "react";
import { Download, Pencil, Save, Trash2 } from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import {
  areaFactor,
  calculateLeadCosting,
  calculateStockFit,
  numberValue,
  unitLabel,
  type LeadCostingLamination,
  type LeadCostingUnit,
} from "@/lib/lead-costing-calculator";
import { LeadCostingPrintingQuotation } from "@/components/lead-costing-printing-quotation";

type Service = { id: string; name: string; examples: string | null; material_guidance: string | null; pricing_basis: string | null; notes: string | null };
type Material = { id: string; supplier_source: string; name: string; product_code: string | null; roll_description: string | null; roll_width_m: number | null; roll_length_m: number | null; roll_area_m2: number | null; roll_price: number | null; cost_per_m2: number | null; supplier_cost_per_m2: number | null; supplier_cost_per_sq_ft: number | null; source_note: string | null; is_sheet: boolean; is_finishing: boolean };
type Inventory = { id: string; material_id: string; full_rolls_on_hand: number | null; remaining_meters: number | null };
type PrinterCost = { id: string; item: string; unit: string | null; listed_cost: number | null; cost_per_unit: number | null; notes: string | null };
type Customer = { id: string; name: string; contact_details: string | null; inquiry: string | null; inquiry_status: string; follow_up_date: string | null; notes: string | null };
type Order = { id: string; order_no: string; order_date: string; customer_name: string; order_description: string; service_id: string | null; material_id: string | null; quantity: number; payment_mode: string; payment_status: string; amount_paid: number; balance_due: number; width: number; height: number; measurement_unit: LeadCostingUnit; material_cost_per_item: number; ink_cost_per_item: number; lamination_cost_per_item: number; waste_cost_per_item: number; total_production_cost: number; total_quotation: number; estimated_profit: number };
type Tab = "calculator" | "printing-quotations" | "services" | "materials" | "inventory" | "sales" | "customers" | "printer";
type CalculatorForm = { serviceId: string; materialId: string; customerName: string; orderDescription: string; paymentMode: string; orderDate: string; amountPaid: string; width: string; height: string; unit: LeadCostingUnit; quantity: string; mediaRate: string; inkRate: string; wasteRate: string; lamination: LeadCostingLamination; policyText: string };
type CustomerForm = { id: string | null; name: string; contactDetails: string; inquiry: string; status: string; followUpDate: string; notes: string };

const inquiryStatuses = ["New inquiry", "Replied", "Awaiting customer", "Follow-up needed", "Quoted", "Confirmed order", "In production", "Ready for pickup", "Completed", "Cancelled / lost"];
const money = (value: number) => `₱${(Number.isFinite(value) ? value : 0).toLocaleString("en-PH", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const escapeHtml = (value: unknown) => String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#39;");
const csvCell = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`;
const today = () => new Date().toISOString().slice(0, 10);
const blankCalculator = (): CalculatorForm => ({ serviceId: "", materialId: "", customerName: "", orderDescription: "", paymentMode: "Cash", orderDate: today(), amountPaid: "0", width: "3", height: "5", unit: "ft", quantity: "1", mediaRate: "4.48", inkRate: "9.27", wasteRate: "0", lamination: "none", policyText: "• Quotation is subject to confirmation of final artwork, dimensions, material availability, and production requirements.\n• Production starts after artwork approval and confirmation of payment terms.\n• Changes after approval may affect the price and delivery schedule.\n• Delivery, installation, rush fees, and taxes are included only if stated in the quotation.\n• Final price and completion date are subject to Huswell Trading's written confirmation." });
const blankCustomer = (): CustomerForm => ({ id: null, name: "", contactDetails: "", inquiry: "", status: "New inquiry", followUpDate: "", notes: "" });
const costPerUnit = (costPerM2: number | null | undefined, unit: LeadCostingUnit) => numberValue(costPerM2) / areaFactor(unit);
const printerBasePerSqFt = (rows: PrinterCost[]) => { const ft = rows.find((row) => row.item === "Average total print cost / sq ft")?.cost_per_unit; if (ft != null) return numberValue(ft); const m2 = rows.find((row) => row.item === "Average total print cost / m²")?.cost_per_unit; if (m2 != null) return numberValue(m2) / 10.7639104167; const inch = rows.find((row) => row.item === "Average total print cost / sq in")?.cost_per_unit; return inch == null ? 9.27 : numberValue(inch) * 144; };
const printerRateForUnit = (rows: PrinterCost[], unit: LeadCostingUnit) => { const base = printerBasePerSqFt(rows); return unit === "ft" ? base : unit === "m" ? base * 10.7639104167 : base / 144; };
const isAveragePrinterReference = (item: string) => ["Average total print cost / m²", "Average total print cost / sq ft", "Average total print cost / sq in"].includes(item);
const inputClass = "mt-1 w-full rounded-md border border-[#cfd8e3] bg-white px-3 py-2 text-[13px] text-[#202938] outline-none focus:border-[#1f4e79]";
const compactButton = "inline-flex items-center justify-center gap-1.5 rounded-md border border-[#cfd8e3] bg-white px-3 py-2 text-[12px] font-medium text-[#1f4e79] hover:bg-[#f4f7fb] disabled:cursor-not-allowed disabled:opacity-60";
const primaryButton = "inline-flex items-center justify-center gap-1.5 rounded-md bg-[#1f4e79] px-3 py-2 text-[12px] font-medium text-white hover:bg-[#173b5c] disabled:cursor-not-allowed disabled:opacity-60";
const tableClass = "app-table w-full min-w-[900px] text-[12px]";

export function LeadCostingIndexWorkspace({ organizationId }: { organizationId: string }) {
  const client = useMemo(() => createClient(), []);
  const [tab, setTab] = useState<Tab>("calculator");
  const [services, setServices] = useState<Service[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [inventory, setInventory] = useState<Inventory[]>([]);
  const [printerCosts, setPrinterCosts] = useState<PrinterCost[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [form, setForm] = useState<CalculatorForm>(blankCalculator);
  const [customerForm, setCustomerForm] = useState<CustomerForm>(blankCustomer);
  const [mediaSearch, setMediaSearch] = useState("");
  const [mediaSupplier, setMediaSupplier] = useState("");
  const [inventorySearch, setInventorySearch] = useState("");
  const [salesSearch, setSalesSearch] = useState("");
  const [salesStatus, setSalesStatus] = useState("All payment statuses");
  const [customerSearch, setCustomerSearch] = useState("");
  const [customerStatus, setCustomerStatus] = useState("All inquiry statuses");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    const read = async <T,>(table: string, order: string) => { const { data, error: readError } = await client.from(table).select("*").eq("organization_id", organizationId).order(order, { ascending: true }); if (readError) throw readError; return (data ?? []) as T[]; };
    try {
      const [loadedServices, loadedMaterials, loadedInventory, loadedPrinterCosts, loadedCustomers, loadedOrders] = await Promise.all([
        read<Service>("lead_costing_services", "name"), read<Material>("lead_costing_materials", "name"), read<Inventory>("lead_costing_inventory", "updated_at"), read<PrinterCost>("lead_costing_printer_costs", "item"), read<Customer>("lead_costing_customers", "updated_at"), read<Order>("lead_costing_orders", "order_date"),
      ]);
      setServices(loadedServices); setMaterials(loadedMaterials); setInventory(loadedInventory); setPrinterCosts(loadedPrinterCosts); setCustomers(loadedCustomers); setOrders(loadedOrders);
      setForm((current) => ({ ...current, serviceId: current.serviceId || loadedServices[0]?.id || "", materialId: current.materialId || loadedMaterials[0]?.id || "" }));
    } catch (loadError) { setError(loadError instanceof Error ? loadError.message : "Lead costing data could not load. Apply the Lead Costing migration first."); } finally { setLoading(false); }
  }, [client, organizationId]);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => { const channel = client.channel(`lead-costing-data:${organizationId}`); ["lead_costing_services", "lead_costing_materials", "lead_costing_inventory", "lead_costing_printer_costs", "lead_costing_customers", "lead_costing_orders"].forEach((table) => channel.on("postgres_changes", { event: "*", schema: "public", table, filter: `organization_id=eq.${organizationId}` }, () => void load())); channel.subscribe(); return () => { void client.removeChannel(channel); }; }, [client, load, organizationId]);

  const selectedMaterial = materials.find((material) => material.id === form.materialId);
  const selectedService = services.find((service) => service.id === form.serviceId);
  const inventoryByMaterial = useMemo(() => new Map(inventory.map((row) => [row.material_id, row])), [inventory]);
  const calculation = useMemo(() => calculateLeadCosting(form, selectedMaterial), [form, selectedMaterial]);
  const stockCheck = useMemo(() => { const stock = selectedMaterial ? inventoryByMaterial.get(selectedMaterial.id) : undefined; return calculateStockFit({ input: form, material: selectedMaterial, fullRolls: stock?.full_rolls_on_hand, remainingMeters: stock?.remaining_meters }); }, [form, inventoryByMaterial, selectedMaterial]);
  const suppliers = useMemo(() => [...new Set(materials.map((material) => material.supplier_source))].sort(), [materials]);
  const filteredMaterials = useMemo(() => { const query = mediaSearch.trim().toLowerCase(); return materials.filter((material) => (!mediaSupplier || material.supplier_source === mediaSupplier) && (!query || [material.supplier_source, material.name, material.product_code, material.roll_description].map((value) => String(value ?? "").toLowerCase()).join(" ").includes(query))); }, [materials, mediaSearch, mediaSupplier]);
  const filteredInventory = useMemo(() => { const query = inventorySearch.trim().toLowerCase(); return materials.filter((material) => !query || [material.supplier_source, material.name, material.product_code, material.roll_description].map((value) => String(value ?? "").toLowerCase()).join(" ").includes(query)); }, [inventorySearch, materials]);
  const filteredOrders = useMemo(() => { const query = salesSearch.trim().toLowerCase(); return orders.filter((order) => (!query || [order.order_no, order.customer_name, order.order_description].map((value) => String(value ?? "").toLowerCase()).join(" ").includes(query)) && (salesStatus === "All payment statuses" || order.payment_status === salesStatus)); }, [orders, salesSearch, salesStatus]);
  const filteredCustomers = useMemo(() => { const query = customerSearch.trim().toLowerCase(); return customers.filter((customer) => (!query || [customer.name, customer.contact_details, customer.inquiry, customer.notes].map((value) => String(value ?? "").toLowerCase()).join(" ").includes(query)) && (customerStatus === "All inquiry statuses" || customer.inquiry_status === customerStatus)); }, [customerSearch, customerStatus, customers]);
  const setField = <K extends keyof CalculatorForm>(key: K, value: CalculatorForm[K]) => setForm((current) => ({ ...current, [key]: value }));
  const handleUnitChange = (unit: LeadCostingUnit) => setForm((current) => ({ ...current, unit, mediaRate: selectedMaterial ? String(costPerUnit(selectedMaterial.cost_per_m2, unit)) : current.mediaRate, inkRate: String(printerRateForUnit(printerCosts, unit)) }));
  const handleMaterialChange = (materialId: string) => { const material = materials.find((row) => row.id === materialId); setForm((current) => ({ ...current, materialId, mediaRate: material ? String(costPerUnit(material.cost_per_m2, current.unit)) : current.mediaRate })); };

  const saveOrder = async () => {
    setSaving(true); setMessage(null); setError(null);
    try {
      if (!calculation.valid || !selectedMaterial || !selectedService) throw new Error("Enter dimensions and select a service and material before saving.");
      const { data: userData } = await client.auth.getUser(); if (!userData.user) throw new Error("Sign in again before saving a costing order.");
      let customerId = customers.find((customer) => customer.name.trim().toLowerCase() === form.customerName.trim().toLowerCase())?.id ?? null;
      if (!customerId && form.customerName.trim()) { const { data: createdCustomer, error: customerError } = await client.from("lead_costing_customers").insert({ organization_id: organizationId, name: form.customerName.trim(), inquiry: `${form.orderDescription.trim() || selectedService.name} - ${calculation.width} x ${calculation.height} ${form.unit} - Qty ${calculation.quantity}`, inquiry_status: "Quoted", created_by: userData.user.id }).select("id").single(); if (customerError) throw customerError; customerId = createdCustomer?.id ?? null; }
      const { error: orderError } = await client.rpc("create_lead_costing_order_from_index", { p_organization_id: organizationId, p_customer_id: customerId, p_service_id: selectedService.id, p_material_id: selectedMaterial.id, p_order_date: form.orderDate || null, p_customer_name: form.customerName.trim() || "Walk-in / not specified", p_order_description: form.orderDescription.trim() || selectedService.name, p_payment_mode: form.paymentMode, p_amount_paid: calculation.amountPaid, p_width: calculation.width, p_height: calculation.height, p_measurement_unit: form.unit, p_quantity: calculation.quantity, p_media_rate: numberValue(form.mediaRate), p_print_rate: numberValue(form.inkRate), p_waste_allowance_per_project: calculation.wasteProject, p_lamination_type: form.lamination, p_policy_text: form.policyText });
      if (orderError) throw orderError; setMessage("Costing saved to Huswell Sales and Customer Records."); setTab("sales"); await load();
    } catch (saveError) { setError(saveError instanceof Error ? saveError.message : "Costing order could not be saved."); } finally { setSaving(false); }
  };

  const saveCustomer = async () => {
    setSaving(true); setMessage(null); setError(null);
    try { if (!customerForm.name.trim()) throw new Error("Enter a customer name before saving."); const { data: userData } = await client.auth.getUser(); if (!userData.user) throw new Error("Sign in again before saving a customer."); const payload = { organization_id: organizationId, name: customerForm.name.trim(), contact_details: customerForm.contactDetails.trim() || null, inquiry: customerForm.inquiry.trim() || null, inquiry_status: customerForm.status, follow_up_date: customerForm.followUpDate || null, notes: customerForm.notes.trim() || null, created_by: userData.user.id }; const query = customerForm.id ? client.from("lead_costing_customers").update(payload).eq("id", customerForm.id).eq("organization_id", organizationId) : client.from("lead_costing_customers").insert(payload); const { error: customerError } = await query; if (customerError) throw customerError; setCustomerForm(blankCustomer()); setMessage("Customer record saved."); await load(); } catch (saveError) { setError(saveError instanceof Error ? saveError.message : "Customer record could not be saved."); } finally { setSaving(false); }
  };

  const saveService = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); setSaving(true); setError(null); try { const name = String(data.get("serviceName") ?? "").trim(); if (!name) throw new Error("Service name is required."); const { error: saveError } = await client.from("lead_costing_services").insert({ organization_id: organizationId, name, examples: String(data.get("examples") ?? "").trim() || null, material_guidance: String(data.get("materials") ?? "").trim() || null, pricing_basis: String(data.get("basis") ?? "").trim() || null, notes: String(data.get("notes") ?? "").trim() || null }); if (saveError) throw saveError; event.currentTarget.reset(); setMessage("Service saved."); await load(); } catch (saveError) { setError(saveError instanceof Error ? saveError.message : "Service could not be saved."); } finally { setSaving(false); } };
  const saveMaterial = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); setSaving(true); setError(null); try { const source = String(data.get("source") ?? "").trim(); const name = String(data.get("materialName") ?? "").trim(); if (!source || !name) throw new Error("Supplier/source and material name are required."); const unit = String(data.get("unit") ?? "m") as LeadCostingUnit; const enteredCost = numberValue(String(data.get("cost") ?? "")); const { error: saveError } = await client.from("lead_costing_materials").insert({ organization_id: organizationId, supplier_source: source, name, product_code: String(data.get("code") ?? "").trim() || null, roll_description: String(data.get("roll") ?? "").trim() || null, roll_width_m: data.get("width") ? numberValue(String(data.get("width"))) : null, roll_length_m: data.get("length") ? numberValue(String(data.get("length"))) : null, roll_area_m2: data.get("area") ? numberValue(String(data.get("area"))) : null, roll_price: data.get("rollPrice") ? numberValue(String(data.get("rollPrice"))) : null, cost_per_m2: enteredCost * areaFactor(unit), supplier_cost_per_m2: unit === "m" ? enteredCost : null, supplier_cost_per_sq_ft: unit === "ft" ? enteredCost : null, source_note: String(data.get("sourceNote") ?? "").trim() || null, is_sheet: data.get("isSheet") === "on", is_finishing: data.get("isFinishing") === "on" }); if (saveError) throw saveError; event.currentTarget.reset(); setMessage("Material saved."); await load(); } catch (saveError) { setError(saveError instanceof Error ? saveError.message : "Material could not be saved."); } finally { setSaving(false); } };

  const updateMaterialCost = async (material: Material, unit: LeadCostingUnit, value: string) => { const { error: updateError } = await client.from("lead_costing_materials").update({ cost_per_m2: Math.max(0, numberValue(value)) * areaFactor(unit) }).eq("id", material.id).eq("organization_id", organizationId); if (updateError) setError(updateError.message); else { setMessage("Internal material rate updated."); await load(); } };
  const updatePrinterCost = async (row: PrinterCost, value: string) => { const { error: updateError } = await client.from("lead_costing_printer_costs").update({ cost_per_unit: value === "" ? null : Math.max(0, numberValue(value)) }).eq("id", row.id).eq("organization_id", organizationId); if (updateError) setError(updateError.message); else { setMessage("Printer reference updated."); await load(); } };
  const updateInventory = async (materialId: string, key: "full_rolls_on_hand" | "remaining_meters", value: string) => { const current = inventoryByMaterial.get(materialId); const { data: userData } = await client.auth.getUser(); const payload = { organization_id: organizationId, material_id: materialId, full_rolls_on_hand: current?.full_rolls_on_hand ?? null, remaining_meters: current?.remaining_meters ?? null, updated_by: userData.user?.id ?? null }; const nextValue = value === "" ? null : Math.max(0, numberValue(value)); if (key === "full_rolls_on_hand") payload.full_rolls_on_hand = nextValue; else payload.remaining_meters = nextValue; const { error: updateError } = await client.from("lead_costing_inventory").upsert(payload, { onConflict: "organization_id,material_id" }); if (updateError) setError(updateError.message); else await load(); };
  const updateOrderStatus = async (order: Order, status: string) => { const total = numberValue(order.total_quotation); const paid = status === "Paid in full" ? total : status === "Unpaid" ? 0 : Math.min(total, numberValue(order.amount_paid)); const { error: updateError } = await client.from("lead_costing_orders").update({ payment_status: status, amount_paid: paid, balance_due: Math.max(0, total - paid) }).eq("id", order.id).eq("organization_id", organizationId); if (updateError) setError(updateError.message); else await load(); };
  const deleteRow = async (table: string, id: string, label: string) => { if (!window.confirm(`Delete this ${label}?`)) return; const { error: deleteError } = await client.from(table).delete().eq("id", id).eq("organization_id", organizationId); if (deleteError) setError(deleteError.message); else { setMessage(`${label} deleted.`); await load(); } };
  const clearSales = async () => { if (!window.confirm("Delete all saved Lead & Costing orders for this organization?")) return; const { error: deleteError } = await client.from("lead_costing_orders").delete().eq("organization_id", organizationId); if (deleteError) setError(deleteError.message); else { setMessage("Saved sales records cleared."); await load(); } };
  const exportCsv = (filename: string, rows: unknown[][]) => { const url = URL.createObjectURL(new Blob([rows.map((row) => row.map(csvCell).join(",")).join("\r\n")], { type: "text/csv;charset=utf-8" })); const link = document.createElement("a"); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); };
  const exportInventory = () => exportCsv("Huswell_Material_Inventory.csv", [["Supplier", "Material", "Product code", "Roll size", "Full rolls on hand", "Remaining meters", "Total available meters", "Approx total area m2", "Stock status"], ...materials.map((material) => { const stock = inventoryByMaterial.get(material.id); const available = material.roll_length_m == null || (stock?.full_rolls_on_hand == null && stock?.remaining_meters == null) ? null : numberValue(stock?.full_rolls_on_hand) * material.roll_length_m + numberValue(stock?.remaining_meters); return [material.supplier_source, material.name, material.product_code, material.roll_description, stock?.full_rolls_on_hand ?? "", stock?.remaining_meters ?? "", available?.toFixed(2) ?? "", available == null || material.roll_width_m == null ? "" : (available * material.roll_width_m).toFixed(2), available == null ? "Not entered" : available <= 0 ? "Out of stock" : "In stock"]; })]);
  const exportSales = () => exportCsv("Huswell_Sales_Log.csv", [["Order ID", "Date", "Customer", "Description", "Service", "Material", "Size", "Quantity", "Payment Mode", "Payment Status", "Total Sales", "Estimated Cost", "Estimated Profit"], ...orders.map((order) => [order.order_no, order.order_date, order.customer_name, order.order_description, services.find((service) => service.id === order.service_id)?.name ?? "", materials.find((material) => material.id === order.material_id)?.name ?? "", `${order.width} × ${order.height} ${order.measurement_unit}`, order.quantity, order.payment_mode, order.payment_status, order.total_quotation, order.total_production_cost, order.estimated_profit])]);
  const exportCustomers = () => exportCsv("Huswell_Customers.csv", [["Customer", "Contact details", "Inquiry", "Status", "Follow-up date", "Notes"], ...customers.map((customer) => [customer.name, customer.contact_details, customer.inquiry, customer.inquiry_status, customer.follow_up_date, customer.notes])]);
  const printQuote = () => { const popup = window.open("", "_blank", "width=900,height=700"); if (!popup) { setError("The print window was blocked. Allow pop-ups for this site."); return; } popup.document.write(`<!doctype html><html><head><title>Huswell Costing Quote</title><style>body{font:14px Arial;color:#202938;padding:32px}h1{color:#1f4e79}.row{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #edf0f5;padding:8px 0}.total{font-size:18px;font-weight:bold;color:#13845a}.note{margin-top:24px;color:#687386;font-size:12px;white-space:pre-wrap}</style></head><body><h1>Huswell Trading</h1><p>${escapeHtml(form.orderDate)}</p><div class="row"><span>Customer</span><strong>${escapeHtml(form.customerName || "Walk-in / not specified")}</strong></div><div class="row"><span>Service</span><strong>${escapeHtml(selectedService?.name || "Not selected")}</strong></div><div class="row"><span>Material</span><strong>${escapeHtml(selectedMaterial?.name || "Not selected")}</strong></div><div class="row"><span>Size / quantity</span><strong>${escapeHtml(`${calculation.width} x ${calculation.height} ${form.unit}; ${calculation.quantity}`)}</strong></div><div class="row"><span>Cost / item</span><strong>${escapeHtml(money(calculation.totalCostPerItem))}</strong></div><div class="row total"><span>Total production cost</span><strong>${escapeHtml(money(calculation.totalOrderCost))}</strong></div><div class="row"><span>Paid / balance</span><strong>${escapeHtml(`${money(calculation.amountPaid)} / ${money(calculation.balance)}`)}</strong></div><div class="note">${escapeHtml(form.policyText)}</div><script>window.onload=()=>window.print();</script></body></html>`); popup.document.close(); };
  const printOrder = (order: Order, copy: "customer" | "admin") => { const popup = window.open("", "_blank", "width=900,height=700"); if (!popup) { setError("The print window was blocked. Allow pop-ups for this site."); return; } popup.document.write(`<!doctype html><html><head><title>${escapeHtml(copy)} - ${escapeHtml(order.order_no)}</title><style>body{font:14px Arial;color:#202938;padding:32px}h1{color:#1f4e79}.row{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #edf0f5;padding:8px 0}.total{font-size:18px;font-weight:bold;color:#13845a}</style></head><body><h1>Huswell Trading</h1><p>${escapeHtml(copy)} | ${escapeHtml(order.order_no)} | ${escapeHtml(order.order_date)}</p><div class="row"><span>Customer</span><strong>${escapeHtml(order.customer_name)}</strong></div><div class="row"><span>Description</span><strong>${escapeHtml(order.order_description)}</strong></div><div class="row"><span>Quantity</span><strong>${escapeHtml(order.quantity)}</strong></div><div class="row"><span>Payment</span><strong>${escapeHtml(order.payment_status)}</strong></div><div class="row total"><span>Total production cost</span><strong>${escapeHtml(money(numberValue(order.total_production_cost)))}</strong></div><script>window.onload=()=>window.print();</script></body></html>`); popup.document.close(); };

  if (loading) return <div className="rounded-md border border-[#dfe5ed] bg-white p-6 text-[13px] text-[#687386]">Loading Lead &amp; Costing Coordinator data...</div>;
  const stockClass = stockCheck.status.startsWith("Enough") ? "text-[#13845a]" : stockCheck.status.startsWith("Short") ? "text-[#a12d36]" : "text-[#687386]";
  const stats = { revenue: orders.reduce((sum, order) => sum + numberValue(order.total_quotation), 0), cost: orders.reduce((sum, order) => sum + numberValue(order.total_production_cost), 0), profit: orders.reduce((sum, order) => sum + numberValue(order.estimated_profit), 0), paid: orders.filter((order) => order.payment_status === "Paid in full").reduce((sum, order) => sum + numberValue(order.total_quotation), 0) };

  return <div className="lead-costing-workspace space-y-4">
    <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e4e8ef] pb-3"><div><h2 className="text-[18px] font-medium text-[#1f4e79]">Lead &amp; Costing Coordinator</h2><p className="mt-1 text-[12px] text-[#687386]">Printing service costing, materials, inventory, sales, customer follow-up, and printing quotations.</p></div><div className="text-right text-[11px] text-[#687386]">{materials.length} materials · {orders.length} saved orders</div></div>
    {message && <div className="rounded-md border border-[#b9dec9] bg-[#f0fbf4] px-3 py-2 text-[12px] text-[#17623b]" role="status">{message}</div>}{error && <div className="rounded-md border border-[#efc4c8] bg-[#fff5f5] px-3 py-2 text-[12px] text-[#9d2831]" role="alert">{error}</div>}
    <div className="lead-costing-tabs app-tabs overflow-x-auto">{([ ["calculator", "Live Calculator"], ["printing-quotations", "Printing Quotations"], ["services", "Service Menu"], ["materials", "Media Price List"], ["inventory", "Material Inventory"], ["sales", "Sales Dashboard"], ["customers", "Customer Records"], ["printer", "Ink"] ] as [Tab, string][]).map(([id, label]) => <button key={id} type="button" aria-current={tab === id ? "page" : undefined} onClick={() => setTab(id)} className="app-tab" data-active={tab === id ? "true" : "false"}>{label}</button>)}</div>

    {tab === "printing-quotations" && <LeadCostingPrintingQuotation organizationId={organizationId} materials={materials} printerCosts={printerCosts} />}
    {tab === "calculator" && <div className="grid gap-4 xl:grid-cols-[minmax(0,1.1fr)_minmax(340px,.9fr)]"><section className="rounded-md border border-[#dfe5ed] bg-white p-4"><h3 className="mb-3 text-[15px] font-medium text-[#1f4e79]">Order details &amp; production costs</h3><div className="grid gap-3 md:grid-cols-2"><label className="text-[12px] font-medium text-[#465a74] md:col-span-2">Service type<select className={inputClass} value={form.serviceId} onChange={(event) => setField("serviceId", event.target.value)}><option value="">Select service</option>{services.map((service) => <option key={service.id} value={service.id}>{service.name}</option>)}</select></label><label className="text-[12px] font-medium text-[#465a74] md:col-span-2">Media / material<select className={inputClass} value={form.materialId} onChange={(event) => handleMaterialChange(event.target.value)}><option value="">Select material</option>{materials.map((material) => <option key={material.id} value={material.id}>{material.name} — {material.supplier_source}</option>)}</select>{selectedMaterial && <span className="mt-1 block text-[11px] font-normal text-[#687386]">{selectedMaterial.supplier_source} · {selectedMaterial.product_code || "No product code"} · {selectedMaterial.roll_description || "Dimensions unavailable"}</span>}</label><div className="border-b border-[#e4e8ef] pb-1 text-[11px] font-semibold uppercase tracking-[0.07em] text-[#2378d4] md:col-span-2">Customer &amp; order details</div><label className="text-[12px] font-medium text-[#465a74]">Customer name<input className={inputClass} value={form.customerName} onChange={(event) => setField("customerName", event.target.value)} /></label><label className="text-[12px] font-medium text-[#465a74]">Order description<input className={inputClass} value={form.orderDescription} onChange={(event) => setField("orderDescription", event.target.value)} /></label><label className="text-[12px] font-medium text-[#465a74]">Mode of payment<select className={inputClass} value={form.paymentMode} onChange={(event) => setField("paymentMode", event.target.value)}><option>Cash</option><option>GCash</option><option>Bank transfer</option><option>Credit / terms (approval required)</option><option>Other / to be agreed</option></select></label><label className="text-[12px] font-medium text-[#465a74]">Amount paid<input className={inputClass} type="number" min="0" step="0.01" value={form.amountPaid} onChange={(event) => setField("amountPaid", event.target.value)} /></label><div className="text-[12px] text-[#687386] md:col-span-2">{calculation.paymentStatus} · Paid: {money(calculation.amountPaid)} · Balance: {money(calculation.balance)}</div><label className="text-[12px] font-medium text-[#465a74]">Quotation date<input className={inputClass} type="date" value={form.orderDate} onChange={(event) => setField("orderDate", event.target.value)} /></label><label className="text-[12px] font-medium text-[#465a74] md:col-span-2">Customer policies / terms<textarea className={`${inputClass} min-h-24`} value={form.policyText} onChange={(event) => setField("policyText", event.target.value)} /></label><div className="border-b border-[#e4e8ef] pb-1 text-[11px] font-semibold uppercase tracking-[0.07em] text-[#2378d4] md:col-span-2">Job dimensions</div><label className="text-[12px] font-medium text-[#465a74]">Width<input className={inputClass} type="number" min="0" step="any" value={form.width} onChange={(event) => setField("width", event.target.value)} /></label><label className="text-[12px] font-medium text-[#465a74]">Height<input className={inputClass} type="number" min="0" step="any" value={form.height} onChange={(event) => setField("height", event.target.value)} /></label><label className="text-[12px] font-medium text-[#465a74]">Measurement unit<select className={inputClass} value={form.unit} onChange={(event) => handleUnitChange(event.target.value as LeadCostingUnit)}><option value="ft">Feet (ft)</option><option value="in">Inches (in)</option><option value="m">Meters (m)</option></select></label><label className="text-[12px] font-medium text-[#465a74]">Quantity<input className={inputClass} type="number" min="1" step="1" value={form.quantity} onChange={(event) => setField("quantity", event.target.value)} /></label><div className="border-b border-[#e4e8ef] pb-1 text-[11px] font-semibold uppercase tracking-[0.07em] text-[#2378d4] md:col-span-2">Material &amp; ink cost inputs</div><label className="text-[12px] font-medium text-[#465a74]">Media cost (₱ / {unitLabel(form.unit)})<input className={inputClass} type="number" min="0" step="any" value={form.mediaRate} onChange={(event) => setField("mediaRate", event.target.value)} /></label><label className="text-[12px] font-medium text-[#465a74]">Ink (₱ / {unitLabel(form.unit)})<input className={inputClass} type="number" min="0" step="any" value={form.inkRate} onChange={(event) => setField("inkRate", event.target.value)} /></label><label className="text-[12px] font-medium text-[#465a74]">Media wastage allowance (₱ per project)<input className={inputClass} type="number" min="0" step="0.01" value={form.wasteRate} onChange={(event) => setField("wasteRate", event.target.value)} /></label><label className="text-[12px] font-medium text-[#465a74]">Lamination finish<select className={inputClass} value={form.lamination} onChange={(event) => setField("lamination", event.target.value as LeadCostingLamination)}><option value="none">No lamination</option><option value="matte">Matte</option><option value="glossy">Glossy</option></select></label></div><div className="mt-4 flex flex-wrap gap-2"><button type="button" className={primaryButton} disabled={saving || !calculation.valid} onClick={() => void saveOrder()}><Save size={14} />{saving ? "Saving..." : "Save order to Sales"}</button><button type="button" className={primaryButton} onClick={() => { void navigator.clipboard.writeText(`Customer: ${form.customerName || "Walk-in / not specified"}\nTotal production cost: ${money(calculation.totalOrderCost)}`); setMessage("Quotation summary copied."); }}>Copy quotation summary</button><button type="button" className={compactButton} onClick={printQuote}>Print Customer + Admin Copies</button><button type="button" className={compactButton} onClick={() => setForm({ ...blankCalculator(), serviceId: services[0]?.id ?? "", materialId: materials[0]?.id ?? "" })}>Reset sample values</button></div></section><section className="space-y-3"><div className="rounded-md border border-[#dfe5ed] bg-white p-4"><h3 className="mb-3 text-[15px] font-medium text-[#1f4e79]">Automatic material &amp; ink costing results</h3><div className="grid gap-2 text-[13px]">{[["Print area", `${calculation.areaPerItem.toLocaleString("en-PH", { maximumFractionDigits: 4 })} ${unitLabel(form.unit)}`], ["Equivalent area (m²)", `${calculation.areaM2PerItem.toLocaleString("en-PH", { maximumFractionDigits: 4 })} m²`], ["Media cost / item (before wastage)", money(calculation.mediaPerItem)], ["Media wastage allowance / item", money(calculation.wastePerItem)], ["Total wastage allowance / project", money(calculation.wasteProject)], ["Ink cost / item", money(calculation.inkPerItem)], ["Lamination / finishing / item", money(calculation.laminationPerItem)], ["Total production cost / item", money(calculation.totalCostPerItem)], ["Total production cost (quantity)", money(calculation.totalOrderCost)]].map(([label, value]) => <div key={label} className="flex items-start justify-between gap-4 border-b border-[#edf0f5] py-2"><span className="text-[#687386]">{label}</span><strong className="text-right text-[#202938]">{value}</strong></div>)}</div><div className="mt-3 rounded-md bg-[#13845a] p-4 text-white"><div className="text-[11px] opacity-80">Total production cost</div><div className="text-[26px] font-medium">{money(calculation.totalOrderCost)}</div><div className="text-[12px]">{calculation.paymentStatus} · Paid: {money(calculation.amountPaid)} · Balance: {money(calculation.balance)}</div></div></div><div className="rounded-md border border-[#dfe5ed] bg-white p-4"><h3 className="mb-3 text-[15px] font-medium text-[#1f4e79]">Material quantity check</h3><div className="grid gap-2 text-[13px]"><div className="flex justify-between"><span className="text-[#687386]">Selected roll width</span><strong>{stockCheck.plan.rollWidthM ? `${stockCheck.plan.rollWidthM.toFixed(2)} m` : "Not available"}</strong></div><div className="flex justify-between"><span className="text-[#687386]">Estimated roll length required</span><strong>{stockCheck.requiredLength ? `${stockCheck.requiredLength.toFixed(2)} m incl. 10% reserve` : "Cannot estimate"}</strong></div><div className="flex justify-between"><span className="text-[#687386]">Estimated rolls required</span><strong>{stockCheck.requiredRolls || "—"}</strong></div><div className="flex justify-between"><span className="text-[#687386]">Stock check</span><strong className={stockClass}>{stockCheck.status}</strong></div></div><button type="button" className={`${compactButton} mt-3`} onClick={() => setTab("inventory")}>Update material inventory</button></div></section></div>}

    {tab === "services" && <section className="space-y-3"><form onSubmit={saveService} className="rounded-md border border-[#dfe5ed] bg-white p-4"><h3 className="mb-3 text-[15px] font-medium text-[#1f4e79]">Add service</h3><div className="grid gap-2 md:grid-cols-5"><input className={inputClass} name="serviceName" placeholder="Service name" /><input className={inputClass} name="examples" placeholder="Examples" /><input className={inputClass} name="materials" placeholder="Suggested media" /><input className={inputClass} name="basis" placeholder="Pricing basis" /><input className={inputClass} name="notes" placeholder="Notes" /></div><button type="submit" className={`${primaryButton} mt-3`} disabled={saving}><Save size={14} />Save service</button></form><div className="overflow-x-auto"><table className={tableClass}><thead><tr><th>Service</th><th>Example products</th><th>Suggested media family</th><th>Pricing basis</th><th>Notes</th></tr></thead><tbody>{services.map((service) => <tr key={service.id}><td>{service.name}</td><td>{service.examples || "—"}</td><td>{service.material_guidance || "—"}</td><td>{service.pricing_basis || "—"}</td><td>{service.notes || "—"}</td></tr>)}</tbody></table></div></section>}

    {tab === "materials" && <section className="space-y-3"><form onSubmit={saveMaterial} className="rounded-md border border-[#dfe5ed] bg-white p-4"><h3 className="mb-3 text-[15px] font-medium text-[#1f4e79]">Add media / material</h3><div className="grid gap-2 md:grid-cols-4 lg:grid-cols-6"><input className={inputClass} name="source" placeholder="Supplier / source" /><input className={inputClass} name="materialName" placeholder="Material" /><input className={inputClass} name="code" placeholder="Product code" /><input className={inputClass} name="roll" placeholder="Roll / sheet description" /><input className={inputClass} name="width" type="number" min="0" step="any" placeholder="Roll width (m)" /><input className={inputClass} name="length" type="number" min="0" step="any" placeholder="Roll length (m)" /><input className={inputClass} name="area" type="number" min="0" step="any" placeholder="Roll area (m²)" /><input className={inputClass} name="rollPrice" type="number" min="0" step="any" placeholder="Roll price" /><input className={inputClass} name="cost" type="number" min="0" step="any" placeholder="Internal cost" /><select className={inputClass} name="unit" defaultValue="m"><option value="m">Cost per m²</option><option value="ft">Cost per sq ft</option><option value="in">Cost per sq in</option></select><input className={inputClass} name="sourceNote" placeholder="Source note" /><label className="flex items-center gap-2 text-[12px] text-[#465a74]"><input name="isSheet" type="checkbox" /> Sheet</label><label className="flex items-center gap-2 text-[12px] text-[#465a74]"><input name="isFinishing" type="checkbox" /> Finishing</label></div><button type="submit" className={`${primaryButton} mt-3`} disabled={saving}><Save size={14} />Save material</button></form><div className="flex flex-wrap items-end gap-2"><div className="rounded-md border border-[#dfe5ed] bg-white px-3 py-2 text-[12px] text-[#687386]">{materials.length} media entries · {suppliers.length} suppliers/sources</div><input className={`${inputClass} mt-0 max-w-[360px]`} value={mediaSearch} onChange={(event) => setMediaSearch(event.target.value)} placeholder="Search media, code, supplier…" /><select className="rounded-md border border-[#cfd8e3] bg-white px-3 py-2 text-[12px]" value={mediaSupplier} onChange={(event) => setMediaSupplier(event.target.value)}><option value="">All suppliers / sources</option>{suppliers.map((supplier) => <option key={supplier}>{supplier}</option>)}</select></div><div className="overflow-x-auto"><table className={`${tableClass} min-w-[1500px]`}><thead><tr><th>Supplier/source</th><th>Media / product</th><th>Product code</th><th>Roll size</th><th>Roll area</th><th>Roll price</th><th>Price / m²</th><th>Price / sq ft</th><th>Cost / m²</th><th>Cost / sq ft</th><th>Cost / sq in</th><th>Source</th><th>Actions</th></tr></thead><tbody>{filteredMaterials.map((material) => <tr key={material.id}><td>{material.supplier_source}</td><td><strong>{material.name}</strong>{material.is_sheet && <div className="text-[10px] text-[#687386]">Sheet material</div>}{material.is_finishing && <div className="text-[10px] text-[#687386]">Finishing</div>}</td><td>{material.product_code || "—"}</td><td>{material.roll_description || "—"}</td><td>{material.roll_area_m2 == null ? "—" : `${numberValue(material.roll_area_m2).toFixed(2)} m²`}</td><td>{material.roll_price == null ? "—" : money(numberValue(material.roll_price))}</td><td>{material.supplier_cost_per_m2 == null ? "—" : money(numberValue(material.supplier_cost_per_m2))}</td><td>{material.supplier_cost_per_sq_ft == null ? "—" : money(numberValue(material.supplier_cost_per_sq_ft))}</td><td><input className="w-24 rounded border border-[#cfd8e3] px-2 py-1" type="number" min="0" step="any" defaultValue={material.cost_per_m2 ?? ""} onBlur={(event) => void updateMaterialCost(material, "m", event.target.value)} /></td><td><input className="w-24 rounded border border-[#cfd8e3] px-2 py-1" type="number" min="0" step="any" defaultValue={costPerUnit(material.cost_per_m2, "ft")} onBlur={(event) => void updateMaterialCost(material, "ft", event.target.value)} /></td><td><input className="w-24 rounded border border-[#cfd8e3] px-2 py-1" type="number" min="0" step="any" defaultValue={costPerUnit(material.cost_per_m2, "in")} onBlur={(event) => void updateMaterialCost(material, "in", event.target.value)} /></td><td className="max-w-[260px]">{material.source_note || "—"}</td><td><button type="button" className="text-[#a12d36]" onClick={() => void deleteRow("lead_costing_materials", material.id, "material")}>Delete</button></td></tr>)}</tbody></table></div></section>}

    {tab === "inventory" && <section className="space-y-3"><div className="flex flex-wrap items-end justify-between gap-2"><input className={`${inputClass} mt-0 max-w-[360px]`} value={inventorySearch} onChange={(event) => setInventorySearch(event.target.value)} placeholder="Search material, code, supplier…" /><button type="button" className={compactButton} onClick={exportInventory}><Download size={14} />Export stock CSV</button></div><div className="overflow-x-auto"><table className={`${tableClass} min-w-[1200px]`}><thead><tr><th>Supplier / source</th><th>Material</th><th>Product code</th><th>Roll size</th><th>Full rolls on hand</th><th>Remaining meters across open rolls</th><th>Total available meters</th><th>Approx. total area</th><th>Stock status</th></tr></thead><tbody>{filteredInventory.map((material) => { const row = inventoryByMaterial.get(material.id); const available = material.roll_length_m == null || (row?.full_rolls_on_hand == null && row?.remaining_meters == null) ? null : numberValue(row?.full_rolls_on_hand) * material.roll_length_m + numberValue(row?.remaining_meters); return <tr key={material.id}><td>{material.supplier_source}</td><td>{material.name}</td><td>{material.product_code || "—"}</td><td>{material.roll_description || "—"}</td><td><input className="w-24 rounded border border-[#cfd8e3] px-2 py-1" type="number" min="0" step="1" value={row?.full_rolls_on_hand ?? ""} onChange={(event) => void updateInventory(material.id, "full_rolls_on_hand", event.target.value)} /></td><td><input className="w-24 rounded border border-[#cfd8e3] px-2 py-1" type="number" min="0" step="0.01" value={row?.remaining_meters ?? ""} onChange={(event) => void updateInventory(material.id, "remaining_meters", event.target.value)} /></td><td>{available == null ? "—" : `${available.toFixed(2)} m`}</td><td>{available == null || material.roll_width_m == null ? "—" : `${(available * material.roll_width_m).toFixed(2)} m²`}</td><td>{available == null ? "Not entered" : available <= 0 ? "Out of stock" : "In stock"}</td></tr>; })}</tbody></table></div><p className="text-[12px] text-[#687386]">Enter full rolls and the combined remaining meters across opened rolls. Counts are organization-scoped and feed the calculator’s 10% safety-reserve check.</p></section>}

    {tab === "sales" && <section className="space-y-3"><div className="grid gap-3 md:grid-cols-5">{[["Total recorded sales", stats.revenue], ["Saved orders", orders.length], ["Estimated gross profit", stats.profit], ["Estimated production cost", stats.cost], ["Paid sales", stats.paid]].map(([label, value]) => <div key={label as string} className="rounded-md border border-[#dfe5ed] bg-white p-3"><div className="text-[11px] text-[#687386]">{label}</div><strong className="mt-1 block text-[20px] font-medium text-[#1f4e79]">{typeof value === "number" ? money(value) : value}</strong></div>)}</div><div className="flex flex-wrap items-end justify-between gap-2"><input className={`${inputClass} mt-0 max-w-[360px]`} value={salesSearch} onChange={(event) => setSalesSearch(event.target.value)} placeholder="Search customer, order, service…" /><div className="flex flex-wrap gap-2"><select className="rounded-md border border-[#cfd8e3] bg-white px-3 py-2 text-[12px]" value={salesStatus} onChange={(event) => setSalesStatus(event.target.value)}><option>All payment statuses</option><option>Unpaid</option><option>Deposit paid</option><option>Partially paid</option><option>Paid in full</option></select><button type="button" className={compactButton} onClick={exportSales}><Download size={14} />Export sales CSV</button><button type="button" className={compactButton} onClick={() => void clearSales()} disabled={!orders.length}><Trash2 size={14} />Clear saved sales</button></div></div><div className="overflow-x-auto"><table className={`${tableClass} min-w-[1400px]`}><thead><tr><th>Date</th><th>Customer</th><th>Order / service</th><th>Qty</th><th>Payment mode</th><th>Payment status</th><th>Total sales</th><th>Estimated cost</th><th>Estimated profit</th><th>Print</th><th>Action</th></tr></thead><tbody>{filteredOrders.map((order) => <tr key={order.id}><td>{order.order_date}</td><td>{order.customer_name}</td><td><strong>{order.order_description}</strong><div className="text-[10px] text-[#687386]">{services.find((service) => service.id === order.service_id)?.name || "Print service"} · {order.order_no}</div></td><td>{order.quantity}</td><td>{order.payment_mode}</td><td><select className="rounded border border-[#cfd8e3] px-2 py-1" value={order.payment_status} onChange={(event) => void updateOrderStatus(order, event.target.value)}><option>Unpaid</option><option>Deposit paid</option><option>Partially paid</option><option>Paid in full</option></select></td><td>{money(numberValue(order.total_quotation))}</td><td>{money(numberValue(order.total_production_cost))}</td><td>{money(numberValue(order.estimated_profit))}</td><td className="whitespace-nowrap"><button type="button" className="mr-2 text-[#1f4e79]" onClick={() => printOrder(order, "customer")}>Customer</button><button type="button" className="text-[#1f4e79]" onClick={() => printOrder(order, "admin")}>Admin</button></td><td><button type="button" className="text-[#a12d36]" onClick={() => void deleteRow("lead_costing_orders", order.id, "order")}>Delete</button></td></tr>)}</tbody></table></div></section>}

    {tab === "customers" && <section className="space-y-3"><div className="rounded-md border border-[#dfe5ed] bg-white p-4"><h3 className="mb-3 text-[15px] font-medium text-[#1f4e79]">Customer records &amp; inquiry follow-up</h3><div className="grid gap-2 md:grid-cols-3"><input className={inputClass} placeholder="Customer name" value={customerForm.name} onChange={(event) => setCustomerForm((current) => ({ ...current, name: event.target.value }))} /><input className={inputClass} placeholder="Contact details" value={customerForm.contactDetails} onChange={(event) => setCustomerForm((current) => ({ ...current, contactDetails: event.target.value }))} /><input className={inputClass} placeholder="Inquiry / requested service" value={customerForm.inquiry} onChange={(event) => setCustomerForm((current) => ({ ...current, inquiry: event.target.value }))} /><select className={inputClass} value={customerForm.status} onChange={(event) => setCustomerForm((current) => ({ ...current, status: event.target.value }))}>{inquiryStatuses.map((status) => <option key={status}>{status}</option>)}</select><input className={inputClass} type="date" value={customerForm.followUpDate} onChange={(event) => setCustomerForm((current) => ({ ...current, followUpDate: event.target.value }))} /><input className={inputClass} placeholder="Notes" value={customerForm.notes} onChange={(event) => setCustomerForm((current) => ({ ...current, notes: event.target.value }))} /></div><div className="mt-3 flex gap-2"><button type="button" className={primaryButton} disabled={saving} onClick={() => void saveCustomer()}><Save size={14} />{customerForm.id ? "Update customer" : "Save customer record"}</button>{customerForm.id && <button type="button" className={compactButton} onClick={() => setCustomerForm(blankCustomer)}>Clear / cancel edit</button>}</div></div><div className="flex flex-wrap items-end justify-between gap-2"><div className="flex flex-wrap gap-2"><input className={`${inputClass} mt-0 max-w-[360px]`} value={customerSearch} onChange={(event) => setCustomerSearch(event.target.value)} placeholder="Search customer, contact, inquiry…" /><select className="rounded-md border border-[#cfd8e3] bg-white px-3 py-2 text-[12px]" value={customerStatus} onChange={(event) => setCustomerStatus(event.target.value)}><option>All inquiry statuses</option>{inquiryStatuses.map((status) => <option key={status}>{status}</option>)}</select></div><button type="button" className={compactButton} onClick={exportCustomers}><Download size={14} />Export customers CSV</button></div><div className="overflow-x-auto"><table className={`${tableClass} min-w-[1100px]`}><thead><tr><th>Customer</th><th>Contact</th><th>Inquiry</th><th>Status</th><th>Follow-up</th><th>Saved costing / orders</th><th>Notes</th><th>Actions</th></tr></thead><tbody>{filteredCustomers.map((customer) => <tr key={customer.id}><td>{customer.name}</td><td>{customer.contact_details || "—"}</td><td>{customer.inquiry || "—"}</td><td>{customer.inquiry_status}</td><td>{customer.follow_up_date || "—"}</td><td>{orders.filter((order) => order.customer_name.trim().toLowerCase() === customer.name.trim().toLowerCase()).length}</td><td>{customer.notes || "—"}</td><td className="whitespace-nowrap"><button type="button" className="mr-2 text-[#1f4e79]" onClick={() => setCustomerForm({ id: customer.id, name: customer.name, contactDetails: customer.contact_details || "", inquiry: customer.inquiry || "", status: customer.inquiry_status, followUpDate: customer.follow_up_date || "", notes: customer.notes || "" })}><Pencil size={14} /></button><button type="button" className="text-[#a12d36]" onClick={() => void deleteRow("lead_costing_customers", customer.id, "customer") }><Trash2 size={14} /></button></td></tr>)}</tbody></table></div></section>}

    {tab === "printer" && <section className="space-y-3"><div className="rounded-md border border-[#f0d98b] bg-[#fff8e1] p-3 text-[12px] leading-5 text-[#5e4c1c]">Printer and ink reference values are used by the calculator. Verify the approved printer model and base rate before quoting.</div><div className="overflow-x-auto"><table className={`${tableClass} min-w-[800px]`}><thead><tr><th>Cost item</th><th>Unit / quantity</th><th>Listed cost</th><th>Cost per ml / unit</th><th>Notes</th></tr></thead><tbody>{printerCosts.map((row) => <tr key={row.id}><td>{row.item}</td><td>{row.unit || "—"}</td><td>{row.listed_cost == null ? "—" : money(numberValue(row.listed_cost))}</td><td>{isAveragePrinterReference(row.item) ? <input className="w-32 rounded border border-[#cfd8e3] px-2 py-1" type="number" min="0" step="any" defaultValue={row.cost_per_unit ?? ""} onBlur={(event) => void updatePrinterCost(row, event.target.value)} /> : row.cost_per_unit == null ? "—" : numberValue(row.cost_per_unit).toLocaleString("en-PH", { maximumFractionDigits: 6 })}</td><td>{row.notes || "—"}</td></tr>)}</tbody></table></div></section>}
  </div>;
}
